        if (!hasPermission(userRole, 'manage_orders')) { alert('ليس لديك صلاحية لتحديث حالة الطلب'); return; }
        try {
            const { error } = await insforge.database
                .from('orders')
                .update({ status: newStatus })
                .eq('id', orderId);

            if (!error) {
                setOrders(prev => prev.map(o => o.id === orderId ? { ...o, status: newStatus } : o));

                setOrders(prev => {
                    const updated = prev.map(o => o.id === orderId ? { ...o, status: newStatus } : o);
                    computeStats(updated);
                    return updated;
                });
            }
        } catch (err) {
            console.error('Failed to update status', err);
        }
    };

    const computeStats = (data: any[]) => {
        let pending = 0, shipping = 0, completed = 0, cancelled = 0, totalRevenue = 0;
        data.forEach((o: any) => {
            const s = o.status || 'pending';
            if (s === 'pending') pending++;
            else if (s === 'shipping') shipping++;
            else if (s === 'completed') { completed++; totalRevenue += parseFloat(o.total_price || 0); }
            else if (s === 'cancelled') cancelled++;
        });
        setStats({ total: data.length, pending, shipping, completed, cancelled, totalRevenue });
    };

